  // FAQ index page
  faq_hero_title: { en: "Thailand wellness FAQ", ko: "태국 웰니스 FAQ", th: "คำถามที่พบบ่อยเกี่ยวกับเวลเนสในไทย", zh: "泰国康养常见问题", ja: "タイ・ウェルネスFAQ", ar: "الأسئلة الشائعة عن العافية في تايلاند" },
  faq_hero_sub: { en: "Honest answers to the most common questions about yoga retreats, muay thai camps, spa pricing, diving, and digital nomad life in Thailand.", ko: "요가 리트릿, 무에타이 캠프, 스파 가격, 다이빙, 디지털 노마드 생활까지 — 태국에 대한 가장 흔한 질문에 솔직하게 답합니다.", th: "คำตอบตรงไปตรงมาสำหรับคำถามยอดนิยมเกี่ยวกับโยคะรีทรีต ค่ายมวยไทย ราคาสปา การดำน้ำ และชีวิตดิจิทัลโนแมดในไทย", zh: "关于瑜伽静修、泰拳训练营、水疗价格、潜水以及泰国数字游民生活最常见问题的诚实解答。", ja: "ヨガリトリート、ムエタイキャンプ、スパ料金、ダイビング、タイでのデジタルノマド生活について、よくある質問に正直にお答えします。", ar: "إجابات صادقة عن أكثر الأسئلة شيوعًا حول منتجعات اليوغا ومعسكرات الملاكمة التايلاندية وأسعار السبا والغوص وحياة الرحّل الرقميين في تايلاند." },
  faq_curated_badge: { en: "{n} curated questions · cross-checked against 6 sources", ko: "엄선된 질문 {n}개 · 6개 소스 교차 검증", th: "{n} คำถามคัดสรร · ตรวจสอบข้ามจาก 6 แหล่ง", zh: "{n} 个精选问题 · 6 个来源交叉验证", ja: "厳選された{n}の質問 · 6つの情報源でクロスチェック", ar: "{n} سؤالًا مختارًا · تم التحقق عبر 6 مصادر" },
  faq_topic_general: { en: "General", ko: "일반", th: "ทั่วไป", zh: "综合", ja: "一般", ar: "عام" },
  faq_index_title: { en: "FAQ — Thailand yoga, spa, muay thai, diving", ko: "FAQ — 태국 요가·스파·무에타이·다이빙", th: "คำถามที่พบบ่อย — โยคะ สปา มวยไทย ดำน้ำ ในไทย", zh: "常见问题 — 泰国瑜伽、水疗、泰拳、潜水", ja: "FAQ — タイのヨガ・スパ・ムエタイ・ダイビング", ar: "الأسئلة الشائعة — اليوغا والسبا والملاكمة التايلاندية والغوص في تايلاند" },
  faq_index_desc: { en: "Common questions about Thailand wellness, spa, muay thai, yoga retreats, diving certification, and digital nomad coworking. Real data from {n} curated entries.", ko: "태국 웰니스, 스파, 무에타이, 요가 리트릿, 다이빙 자격증, 디지털 노마드 코워킹에 대한 흔한 질문들. 엄선된 {n}개 항목의 실제 데이터.", th: "คำถามทั่วไปเกี่ยวกับเวลเนส สปา มวยไทย โยคะรีทรีต ใบรับรองดำน้ำ และโคเวิร์กกิ้งสำหรับดิจิทัลโนแมดในไทย ข้อมูลจริงจาก {n} รายการคัดสรร", zh: "关于泰国康养、水疗、泰拳、瑜伽静修、潜水认证及数字游民共享办公的常见问题。来自 {n} 个精选条目的真实数据。", ja: "タイのウェルネス、スパ、ムエタイ、ヨガリトリート、ダイビング資格、デジタルノマド向けコワーキングに関するよくある質問。厳選された{n}件の実データ。", ar: "أسئلة شائعة حول العافية والسبا والملاكمة التايلاندية ومنتجعات اليوغا وشهادات الغوص ومساحات العمل المشتركة للرحّل الرقميين في تايلاند. بيانات حقيقية من {n} مدخلًا مختارًا." },

